  const playerEntities=()=>runtime?.entities.filter(e=>e.alive&&e.faction==='player')||[];const enemyEntities=()=>runtime?.entities.filter(e=>e.alive&&e.faction==='enemy')||[];const hostiles=e=>runtime.entities.filter(x=>x.alive&&x.faction!==e.faction);

  function edgeSafeAtCamera(e,cameraY,margin=0){const a=node(e.from),b=node(e.to);if(!a||!b)return false;for(let i=0;i<=12;i++){const t=i/12,p=project(lerp(a.x,b.x,t),lerp(a.z,b.z,t),lerp(a.y,b.y,t),cameraY);if(p.x<margin||p.x>runtime.w-margin||p.y<margin||p.y>runtime.h-margin)return false;}return true;}
  function predictedCameraY(seconds){if(runtime.phase!=='transition')return runtime.cameraY;const t=clamp((runtime.phaseT+seconds)/runtime.stage.timing.travel,0,1);return lerp(runtime.cameraFrom,runtime.cameraTarget,ease(t));}
