  function startMove(ent,edgeId,to){const ed=edge(edgeId);if(!ent?.alive||ent.moving||ent.airborne||!ed||!edgeEnabled(ed)||edgeBusy(ed,ent.id))return false;const from=ent.nodeId,dest=to||opposite(ed,from);if(!from||!dest||opposite(ed,from)!==dest||junctionBusy(dest,ent.id))return false;if(zone(dest)&&!freeSpots(dest,ent.id).length)return false;if(runtime.phase!=='transition'&&!edgeSafeAtCamera(ed,runtime.cameraY,0))return false;if(ent.faction==='enemy'&&runtime.phase==='transition'&&!enemyTransitionAccepts(ed,ent))return false;ent.zoneId=null;ent.slotIdx=null;ent.awaitingBranch=false;ent.moving={kind:'edge',edgeId:ed.id,from,to:dest,t:0,dur:Math.max(.32,edgeLen(ed)/ent.moveSpeed)};return true;}
  function startSlotMove(ent,slot){const z=zone(ent.zoneId);if(!z||ent.moving||ent.airborne||slot===ent.slotIdx||spotOwner(z.id,slot,ent.id))return false;const a={...ent.world},b={...z.spots[slot]};ent.moving={kind:'slot',fromWorld:a,toWorld:b,toSlot:slot,t:0,dur:Math.max(.22,worldDist(a,b)/ent.moveSpeed)};ent.slotIdx=null;return true;}
  function bestArrivalSpot(ent,zoneId,fs){const targets=hostiles(ent).filter(h=>h.zoneId===zoneId&&!h.moving);if(!targets.length)return fs[0].i;let best=fs[0],score=Infinity;for(const s of fs){const d=Math.min(...targets.map(t=>worldDist(s.p,t.world)));if(d<score){score=d;best=s;}}return best.i;}
  function updateMovement(ent,dt){const m=ent.moving;if(!m)return;m.t+=dt;const t=clamp(m.t/m.dur,0,1),q=t*t*(3-2*t);if(m.kind==='slot'){ent.world={x:lerp(m.fromWorld.x,m.toWorld.x,q),z:lerp(m.fromWorld.z,m.toWorld.z,q),y:lerp(m.fromWorld.y,m.toWorld.y,q)};if(t>=1){ent.moving=null;ent.slotIdx=m.toSlot;ent.world={...m.toWorld};}return;}const a=node(m.from),b=node(m.to);if(!a||!b){ent.moving=null;return;}ent.world={x:lerp(a.x,b.x,q),z:lerp(a.z,b.z,q),y:lerp(a.y,b.y,q)};if(t<1)return;ent.moving=null;ent.nodeId=m.to;if(zone(m.to)){const fs=freeSpots(m.to,ent.id);if(fs.length)placeAtZone(ent,m.to,bestArrivalSpot(ent,m.to,fs));else ent.awaitingBranch=true;}else{ent.zoneId=null;ent.slotIdx=null;ent.awaitingBranch=true;if(ent.faction==='enemy')chooseAiBranch(ent);}}
