  function canAttack(a,b){if(!a?.alive||!b?.alive||a.faction===b.faction||a.moving||b.moving||a.airborne||b.airborne||!a.zoneId||!b.zoneId)return false;const d=worldDist(a.world,b.world);if(a.zoneId===b.zoneId)return d<=a.range&&hasLineOfSight(a,b);if(runtime.phase==='transition')return false;return d<=a.range&&hasLineOfSight(a,b);}
  function pickCombatTarget(ent){const list=hostiles(ent).filter(h=>canAttack(ent,h));if(!list.length)return null;list.sort((a,b)=>(a.flagCarrier?-1:0)-(b.flagCarrier?-1:0)||worldDist(ent.world,a.world)-worldDist(ent.world,b.world));return list[0];}
  function desiredCombatSpot(ent,target){const z=zone(ent.zoneId);if(!z||!target||target.zoneId!==z.id)return null;const fs=freeSpots(z.id,ent.id).concat(ent.slotIdx!=null?[{p:z.spots[ent.slotIdx],i:ent.slotIdx}]:[]);let best=null,score=Infinity,desired=ent.range<210?Math.min(105,ent.range*.6):Math.min(ent.range*.72,235);for(const s of fs){const d=worldDist(s.p,target.world),los=hasLineOfSight({...ent,world:s.p},target),v=Math.abs(d-desired)+(los?0:180);if(v<score){score=v;best=s;}}return best;}

  function barrierAttackable(ent,d){return ent?.alive&&!ent.moving&&!ent.airborne&&!d.broken&&worldDist(ent.world,d)<=Math.max(190,ent.range+75);}function attackBarrier(ent,d,scale=1){if(!barrierAttackable(ent,d))return false;d.hp=Math.max(0,d.hp-ent.damage*.72*scale);d.flash=.15;effect('hit',d,'#ffd5a2');if(d.hp<=0)breakDestructible(d,ent.faction);return true;}function breakDestructible(d,by){if(d.broken)return;d.broken=true;d.hp=0;effect('break',d,'#f3d491');coreToast(`${d.name} broken${by==='enemy'?' by the enemy':''}`);}function guardForZone(zoneId){const z=zone(zoneId);if(!z?.guardDestructible)return null;const d=destructible(z.guardDestructible);return d&&!d.broken?d:null;}
  function specialImpulse(def){const sp=def?.special||{},k=String(sp.kind||'').toLowerCase();let knock=Number(sp.knockback||sp.knock||0)||0,launch=0;if(k.includes('heavensfist')||k.includes('launch'))launch=120;if(k.includes('whirlwind'))knock=Math.max(knock,18);return{knock,launch};}
  function applyImpulse(target,attacker,knock,launch){if(!target?.alive||(!knock&&!launch))return;const g=guardForZone(target.zoneId);if(g&&launch<95&&knock<22){effect('guard',target.world,'#d4ecfa');return;}const dx=target.world.x-attacker.world.x,dz=target.world.z-attacker.world.z,len=Math.max(1,Math.hypot(dx,dz));target.lastHitFaction=attacker.faction;target.lastHitT=0;target.zoneId=null;target.nodeId=null;target.slotIdx=null;target.moving=null;target.awaitingBranch=false;target.airborne={vx:dx/len*(52+knock*2.5),vz:dz/len*(32+knock*1.5),vy:Math.max(75,launch||knock*1.8),prevY:target.world.y};}
  function updateAirborne(e,dt){const a=e.airborne;if(!a)return;a.prevY=e.world.y;e.world.x+=a.vx*dt;e.world.z+=a.vz*dt;e.world.y+=a.vy*dt;a.vy-=430*dt;a.vx*=Math.pow(.985,dt*60);a.vz*=Math.pow(.985,dt*60);if(a.vy<=0){const zs=runtime.stage.zones.filter(z=>Math.abs(e.world.x-z.x)<=z.w*.5&&Math.abs(e.world.z-z.z)<=z.d*.5&&a.prevY>=z.y&&e.world.y<=z.y+5).sort((x,y)=>y.y-x.y);for(const z of zs){const fs=freeSpots(z.id,e.id);if(fs.length){placeAtZone(e,z.id,bestArrivalSpot(e,z.id,fs));effect('land',e.world,'#d4ecfa');return;}}}}

  function hurt(target,amount,attacker){if(!target?.alive)return;target.hp-=Math.max(1,amount);target.hitFlash=.12;if(attacker){target.lastHitFaction=attacker.faction;target.lastHitT=0;}effect('damage',target.world,attacker?.faction==='player'?'#f3d491':'#ff8c82');if(target.hp<=0)killEntity(target,'combat',attacker?.faction||null);}
  function loseLife(){if(!runtime||runtime.finished)return;runtime.lives=Math.max(0,runtime.lives-1);coreToast(`Die lost · ${runtime.lives} ${runtime.lives===1?'life':'lives'} remaining`);if(runtime.lives<=0)finish(false,'All 10 lives were lost.');}
  function killEntity(e,reason,creditFaction=null){if(!e?.alive)return;if(e.flagCarrier)dropFlagFromHolder(e,reason);e.alive=false;e.hp=0;if(runtime.selectedId===e.id)runtime.selectedId=null;effect('death',e.world,e.faction==='player'?'#d4ecfa':'#ff8c82');if(e.faction==='player'&&!e.lifeDebited&&reason!=='merge'){e.lifeDebited=true;loseLife();}if(e.faction==='enemy'){const credit=creditFaction==='player'||(e.lastHitFaction==='player'&&e.lastHitT<=3);if(credit){runtime.kills++;runtime.sp=Math.min(999,runtime.sp+7);if(runtime.kills===runtime.killGoal)coreToast(playerHoldsFlag()?'60 defeated · rooftop claimed!':'60 defeated · CLAIM THE FLAG!');}}}
