  function mergeDice(src,dst){if(!src||!dst||src===dst||src.faction!=='player'||dst.faction!=='player'||src.type!=='die'||dst.type!=='die'||src.moving||dst.moving||src.airborne||dst.airborne||src.key!==dst.key||src.dot!==dst.dot||dst.dot>=7)return false;const carry=src.flagCarrier;src.alive=false;src.hp=0;src.lifeDebited=true;src.flagCarrier=false;dst.dot++;dst.damage*=1.22;dst.attackInterval=Math.max(.16,dst.attackInterval/1.12);const ratio=dst.hp/Math.max(1,dst.maxHp);dst.maxHp=Math.round(dst.maxHp*1.22);dst.hp=Math.max(1,dst.maxHp*ratio);if(carry){runtime.flag.holderId=dst.id;runtime.flag.state='held';dst.flagCarrier=true;}runtime.selectedId=dst.id;effect('merge',dst.world,'#f3d491');coreToast(`${dst.name} merged to ${dst.dot} pips`);return true;}

  function flagHomeWorld(){const cfg=runtime.stage.objective.flag,z=zone(cfg.homeZone),slot=clamp(cfg.homeSlot||0,0,z.spots.length-1);return{...z.spots[slot]};}
  function resetFlagHome(initial=false){if(!runtime)return;const cfg=runtime.stage.objective.flag;runtime.flag={state:'home',holderId:null,zoneId:cfg.homeZone,world:flagHomeWorld(),baseWorld:flagHomeWorld(),respawnT:0,bounceT:0};if(!initial)coreToast('The flag returned to the Sign Crown');}
  function flagHolder(){return runtime?.flag?.state==='held'?runtime.entities.find(e=>e.alive&&e.id===runtime.flag.holderId)||null:null;}function playerHoldsFlag(){return flagHolder()?.faction==='player';}
  function pickupFlag(ent){if(!runtime?.flag||!ent?.alive||ent.moving||ent.airborne||!ent.zoneId)return false;const f=runtime.flag;if(f.state==='held'||f.state==='respawning'||ent.zoneId!==f.zoneId||worldDist(ent.world,f.world)>runtime.stage.objective.flag.pickupRange)return false;f.state='held';f.holderId=ent.id;f.zoneId=ent.zoneId;ent.flagCarrier=true;effect('flag',ent.world,ent.faction==='player'?'#55d8ff':'#ff607b');coreToast(ent.faction==='player'?'FLAG CAPTURED!':'The enemy captured the flag!');checkVictory();return true;}
