  function chooseAiBranch(ent){if(!ent?.alive||ent.moving||!ent.nodeId||ent.flagCarrier)return false;let targetZone=null;const carrier=flagHolder();if(carrier?.faction==='player'&&carrier.zoneId)targetZone=carrier.zoneId;else{const fz=flagTargetZone();if(fz)targetZone=fz;}if(!targetZone){const ps=playerEntities().filter(p=>p.zoneId);if(!ps.length)return false;ps.sort((a,b)=>worldDist(ent.world,a.world)-worldDist(ent.world,b.world));targetZone=ps[0].zoneId;}const path=shortestPath(ent.nodeId,targetZone,ent,true);if(!path?.length)return false;const first=path[0],ed=edge(first.edgeId),blocker=blockingDestructible(ed);if(blocker){ent.aiBarrier=blocker.id;return false;}return startMove(ent,ed.id,first.to);}
